document.addEventListener("DOMContentLoaded",()=>{
  const q=id=>document.getElementById(id);if(!q("adminBundleFactoryPanel"))return;
  const state={assets:[],products:[],selected:"",busy:false};
  const toast=msg=>{const el=q("adminToast");if(el){el.hidden=false;el.textContent=msg;setTimeout(()=>el.hidden=true,3200)}};
  const asset=()=>state.assets.find(x=>x.id===q("bundleFactoryAsset")?.value)||null;
  const render=()=>{const sel=q("bundleFactoryAsset");if(sel){const keep=sel.value;sel.innerHTML=state.assets.map(a=>`<option value="${CFS.escape(a.id)}">${CFS.escape(a.name)} · ${CFS.escape(a.rights_status)}</option>`).join("");if(state.assets.some(a=>a.id===keep))sel.value=keep;state.selected=sel.value||""}q("bundleFactoryAssets").innerHTML=state.assets.length?state.assets.map(a=>`<div class="bundle-asset-row"><img src="${CFS.escape(a.preview_url)}" alt=""><div><strong>${CFS.escape(a.name)}</strong><small class="${a.shop_use_allowed?"bundle-rights-ok":"bundle-rights-pending"}">${a.shop_use_allowed?"✓ SHOP-NUTZUNG FREIGEGEBEN":"RECHTE OFFEN"}</small></div></div>`).join(""):'<div class="admin-empty">Noch kein Bild hochgeladen.</div>';const a=asset();if(a){q("bundleFactoryRights").value=a.rights_status;q("bundleFactoryRightsSource").value=a.rights_source||"";q("bundleFactoryRightsNote").value=a.rights_note||""}q("bundleFactoryProducts").innerHTML=state.products.length?state.products.map(p=>`<article class="bundle-product-card ${p.platform==="tiktok"?"tiktok":""}"><img src="${CFS.escape(p.preview?.asset_url||"")}" alt=""><div class="bundle-product-copy"><small>${CFS.escape(p.platform.toUpperCase())} · ${CFS.escape(p.design_variant.toUpperCase())} · ${CFS.escape(p.status.toUpperCase())}</small><input data-product-title="${CFS.escape(p.id)}" maxlength="140" value="${CFS.escape(p.title)}"><textarea data-product-description="${CFS.escape(p.id)}" maxlength="1000" rows="3">${CFS.escape(p.description)}</textarea><select data-product-pricing="${CFS.escape(p.id)}"><option value="free" ${p.pricing_mode==="free"?"selected":""}>FREE</option><option value="beta" ${p.pricing_mode==="beta"?"selected":""}>BETA</option></select><div class="bundle-product-actions"><button class="btn" data-product-save="${CFS.escape(p.id)}">SPEICHERN</button><a class="btn" href="${CFS.escape(p.detail_url)}" target="_blank">VORSCHAU</a><button class="btn ${p.status==="published"?"":"primary"}" data-product-action="${p.status==="published"?"unpublish":"publish"}" data-id="${CFS.escape(p.id)}">${p.status==="published"?"AUS SHOP NEHMEN":"IM SHOP VERÖFFENTLICHEN"}</button></div></div></article>`).join(""):'<div class="admin-empty">Noch keine Produktentwürfe.</div>';q("bundleFactoryProducts").querySelectorAll("[data-product-action]").forEach(btn=>btn.onclick=()=>productAction(btn.dataset.id,btn.dataset.productAction));q("bundleFactoryProducts").querySelectorAll("[data-product-save]").forEach(btn=>btn.onclick=()=>saveProduct(btn.dataset.productSave));};
  const load=async()=>{try{const data=await CFS.json("/api/admin/store/bundle-factory");state.assets=data.assets||[];state.products=data.products||[];render()}catch(e){toast(e.message)}};
  q("bundleFactoryAsset")?.addEventListener("change",render);
  q("bundleFactoryUpload")?.addEventListener("click",async()=>{const file=q("bundleFactoryFile")?.files?.[0];if(!file)return toast("Bitte zuerst ein PNG, JPG oder WebP auswählen.");try{await CFS.json("/api/admin/store/bundle-assets",{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream","X-CFS-File-Name":encodeURIComponent(file.name)},body:file});q("bundleFactoryFile").value="";toast("Bild gespeichert. Jetzt Rechte freigeben.");await load()}catch(e){toast(e.message)}});
  q("bundleFactorySaveRights")?.addEventListener("click",async()=>{const a=asset();if(!a)return toast("Bitte ein Bild auswählen.");const status=q("bundleFactoryRights").value;try{await CFS.json(`/api/admin/store/bundle-assets/${encodeURIComponent(a.id)}/rights`,{method:"PATCH",body:JSON.stringify({rights_status:status,shop_use_allowed:status==="approved",rights_source:q("bundleFactoryRightsSource").value,rights_note:q("bundleFactoryRightsNote").value})});toast(status==="approved"?"Shop-Nutzungsrechte freigegeben.":"Rechtestatus gespeichert.");await load()}catch(e){toast(e.message)}});
  q("bundleFactoryGenerate")?.addEventListener("click",async()=>{const a=asset();if(!a)return toast("Bitte ein Quellbild auswählen.");try{const data=await CFS.json("/api/admin/store/bundle-products/generate",{method:"POST",body:JSON.stringify({asset_id:a.id,title:q("bundleFactoryTitle").value||a.name,platform:q("bundleFactoryPlatform").value,bundle_type:q("bundleFactoryType").value})});toast(`${data.products?.length||0} Designvarianten erzeugt.`);await load()}catch(e){toast(e.message)}});
  async function saveProduct(id){const title=q("bundleFactoryProducts").querySelector(`[data-product-title="${CSS.escape(id)}"]`)?.value||"";const description=q("bundleFactoryProducts").querySelector(`[data-product-description="${CSS.escape(id)}"]`)?.value||"";const pricing_mode=q("bundleFactoryProducts").querySelector(`[data-product-pricing="${CSS.escape(id)}"]`)?.value||"free";try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}`,{method:"PATCH",body:JSON.stringify({title,description,pricing_mode})});toast("Produktentwurf gespeichert.");await load()}catch(e){toast(e.message)}}
  async function productAction(id,action){try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/${action}`,{method:"POST",body:"{}"});toast(action==="publish"?"Produkt ist jetzt im Creator Shop.":"Produkt wurde aus dem Shop genommen.");await load()}catch(e){toast(e.message)}}
  q("bundleFactoryRefresh")?.addEventListener("click",load);load();
});
